static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    auto xShape = context->GetInputShape(0)->GetOriginShape();
    auto wShape = context->GetInputShape(1)->GetOriginShape();

    // Expect 5D input: [N, C_in, D, H, W] and weight: [C_out, C_in, Kd, Kh, Kw]
    std::vector<int64_t> xDims = xShape.GetDims();
    std::vector<int64_t> wDims = wShape.GetDims();

    if (xDims.size() != 5 || wDims.size() != 5) {
        return ge::GRAPH_FAILED;
    }

    uint32_t N  = static_cast<uint32_t>(xDims[0]);
    uint32_t Ci = static_cast<uint32_t>(xDims[1]);
    uint32_t D  = static_cast<uint32_t>(xDims[2]);
    uint32_t H  = static_cast<uint32_t>(xDims[3]);
    uint32_t W  = static_cast<uint32_t>(xDims[4]);

    uint32_t Co = static_cast<uint32_t>(wDims[0]);
    uint32_t Kd = static_cast<uint32_t>(wDims[2]);
    uint32_t Kh = static_cast<uint32_t>(wDims[3]);
    uint32_t Kw = static_cast<uint32_t>(wDims[4]);

    // Assume stride=(1,1,1), padding=(0,0,0), dilation=(1,1,1)
    uint32_t Dout = (D >= Kd) ? (D - Kd + 1) : 0;
    uint32_t Hout = (H >= Kh) ? (H - Kh + 1) : 0;
    uint32_t Wout = (W >= Kw) ? (W - Kw + 1) : 0;

    uint64_t totalLengthOut = static_cast<uint64_t>(N) * Co * Dout * Hout * Wout;

    ConvStandard3dAsymmetricInputAsymmetricKernelCustomTilingData tiling;
    context->SetBlockDim(BLOCK_DIM);

    tiling.set_n(N);
    tiling.set_ci(Ci);
    tiling.set_co(Co);
    tiling.set_d(D);
    tiling.set_h(H);
    tiling.set_w(W);
    tiling.set_kd(Kd);
    tiling.set_kh(Kh);
    tiling.set_kw(Kw);
    tiling.set_dout(Dout);
    tiling.set_hout(Hout);
    tiling.set_wout(Wout);
    tiling.set_totalLengthOut(totalLengthOut);
    tiling.set_tileNum(TILE_NUM);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
